CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS players (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT UNIQUE NOT NULL, password_hash TEXT NOT NULL, display_name TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS wallets (player_id UUID PRIMARY KEY REFERENCES players(id) ON DELETE CASCADE, soft_currency BIGINT NOT NULL DEFAULT 0 CHECK(soft_currency>=0), premium_currency BIGINT NOT NULL DEFAULT 0 CHECK(premium_currency>=0), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS items (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, rarity INT NOT NULL CHECK(rarity BETWEEN 1 AND 6), kind TEXT NOT NULL DEFAULT 'character');
CREATE TABLE IF NOT EXISTS player_inventory (player_id UUID REFERENCES players(id) ON DELETE CASCADE, item_id UUID REFERENCES items(id), quantity BIGINT NOT NULL DEFAULT 0 CHECK(quantity>=0), PRIMARY KEY(player_id,item_id));
CREATE TABLE IF NOT EXISTS gacha_banners (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT UNIQUE NOT NULL, name TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT false, single_cost BIGINT NOT NULL DEFAULT 160, ten_cost BIGINT NOT NULL DEFAULT 1600, pity_5 INT NOT NULL DEFAULT 80, pity_4 INT NOT NULL DEFAULT 10, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gacha_entries (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), banner_id UUID REFERENCES gacha_banners(id) ON DELETE CASCADE, item_id UUID REFERENCES items(id), rarity INT NOT NULL, weight INT NOT NULL CHECK(weight>0), featured BOOLEAN NOT NULL DEFAULT false, UNIQUE(banner_id,item_id));
CREATE TABLE IF NOT EXISTS gacha_pity (player_id UUID REFERENCES players(id) ON DELETE CASCADE, banner_id UUID REFERENCES gacha_banners(id) ON DELETE CASCADE, pulls_since_5 INT NOT NULL DEFAULT 0, pulls_since_4 INT NOT NULL DEFAULT 0, PRIMARY KEY(player_id,banner_id));
CREATE TABLE IF NOT EXISTS gacha_draws (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), player_id UUID REFERENCES players(id) ON DELETE CASCADE, banner_id UUID REFERENCES gacha_banners(id), request_id UUID UNIQUE NOT NULL, quantity INT NOT NULL, cost BIGINT NOT NULL, results JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log (id BIGSERIAL PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, entity_type TEXT, entity_id TEXT, payload JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
